import { useEffect, useState } from "react";
import axios from "axios";

function Cart() {
  const [cart, setCart] = useState([]);

  useEffect(() => {
    const savedCart = JSON.parse(localStorage.getItem("cart")) || [];

    setCart(savedCart);
  }, []);

  // Group items
  const groupedCart = Object.values(
    cart.reduce((acc, item) => {
      if (!acc[item._id]) {
        acc[item._id] = {
          ...item,
          qty: 1,
        };
      } else {
        acc[item._id].qty += 1;
      }

      return acc;
    }, {}),
  );

  // Total
  const total = groupedCart.reduce(
    (sum, item) => sum + item.price * item.qty,
    0,
  );

  // Place order
  const placeOrder = () => {
    const user = JSON.parse(sessionStorage.getItem("user"));

    axios
      .post("http://localhost:5000/orders", {
        userEmail: user.email,
        items: groupedCart,
        total,
      })
      .then(() => {
        alert(`Order placed successfully! Total: ₹${total}`);

        localStorage.removeItem("cart");

        setCart([]);
      })
      .catch((err) => {
        console.log(err);

        alert("Failed to place order");
      });
  };

  // Clear cart
  const clearCart = () => {
    localStorage.removeItem("cart");

    setCart([]);
  };

  return (
    <div style={{ padding: "30px" }}>
      <h1>Your Cart</h1>

      {groupedCart.length === 0 ? (
        <p>Cart is empty</p>
      ) : (
        <>
          {groupedCart.map((item) => (
            <div
              key={item._id}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                border: "1px solid #ddd",
                padding: "15px",
                marginBottom: "15px",
                borderRadius: "10px",
                background: "#fff",
              }}
            >
              <div>
                <h3>{item.name}</h3>

                <p>
                  ₹{item.price} × {item.qty}
                </p>
              </div>

              <h3>₹{item.price * item.qty}</h3>
            </div>
          ))}

          <h2>Total: ₹{total}</h2>

          <button
            onClick={placeOrder}
            style={{
              padding: "10px 20px",
              marginRight: "10px",
            }}
          >
            Place Order
          </button>

          <button
            onClick={clearCart}
            style={{
              padding: "10px 20px",
            }}
          >
            Clear Cart
          </button>
        </>
      )}
    </div>
  );
}

export default Cart;
